from typing import TypeVar, Generic, Union

T = TypeVar('T')

class Ok(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def is_ok(self) -> bool:
        return True

    def is_err(self) -> bool:
        return False

class Err:
    def __init__(self, error: str):
        self.error = error

    def is_ok(self) -> bool:
        return False

    def is_err(self) -> bool:
        return True

Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result[int]:
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    else:
        return Ok(a // b)

def process_and_print(s_val: str, divisor_val: int):
    parsed_result = parse_int(s_val)

    if parsed_result.is_ok():
        int_value = parsed_result.value
        final_result = divide_safe(int_value, divisor_val)
    else:
        final_result = parsed_result

    if final_result.is_ok():
        print(f"Result: {final_result.value}")
    else:
        print(f"Error: {final_result.error}")

process_and_print("10", 2)
process_and_print("10", 0)
process_and_print("abc", 2)

