from typing import TypeVar, Generic, Callable

T = TypeVar('T')
U = TypeVar('U')


class Option(Generic[T]):
    """Base class for Option type"""
    pass


class Some(Option[T]):
    """Some variant containing a value"""
    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Some({self.value})"


class Nothing(Option[T]):
    """Nothing variant representing absence of value"""
    def __repr__(self) -> str:
        return "Nothing"


NOTHING: Option = Nothing()


def findFirst(predicate: Callable[[T], bool], items: list[T]) -> Option[T]:
    """Find first element matching predicate, returns Some(element) or Nothing"""
    for item in items:
        if predicate(item):
            return Some(item)
    return NOTHING


def mapOption(fn: Callable[[T], U], option: Option[T]) -> Option[U]:
    """Apply function to value in Option if Some, otherwise return Nothing"""
    if isinstance(option, Some):
        return Some(fn(option.value))
    return NOTHING


def main():
    list1 = [1, 2, 3, 4, 5]
    first_even = findFirst(lambda x: x % 2 == 0, list1)
    doubled = mapOption(lambda x: x * 2, first_even)

    if isinstance(doubled, Some):
        print(f"Found: {doubled.value}")
    else:
        print("Not found")

    list2 = [1, 3, 5]
    first_even = findFirst(lambda x: x % 2 == 0, list2)
    doubled = mapOption(lambda x: x * 2, first_even)

    if isinstance(doubled, Some):
        print(f"Found: {doubled.value}")
    else:
        print("Not found")


if __name__ == "__main__":
    main()

