type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(Leaf(x), v, Leaf(y)) => {
      let m1 = if v >= x then v else x;
      if m1 >= y then m1 else y
    },
    Node(l, v, r) if v >= find_max(l) && v >= find_max(r) => v,
    Node(l, v, r) if find_max(l) >= find_max(r) => find_max(l),
    Node(_, _, r) => find_max(r)
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let s = tree_sum(tree);
  let m = find_max(tree);
  print("Sum: " ++ show(s) ++ "\n");
  print("Max: " ++ show(m))
}

